//! The shapes of the Unicode tables in [`super::data`] (generated by
//! `cargo xtask tables`), and the lookups the spec and the executable code
//! use on them.

#[allow(unused_imports)]
use vstd::prelude::*;

verus! {

/// UTS #46 §5's Status values.
#[derive(Clone, Copy)]
pub enum Status {
    /// "valid"
    Valid,
    /// "ignored"
    Ignored,
    /// "mapped"
    Mapped,
    /// "deviation"
    Deviation,
    /// "disallowed"
    Disallowed,
}

/// A row of the IDNA Mapping Table: code points `first..=last`, their
/// Status, and their mapping, `IDNA_MAPPING_DATA[mapping_start ..
/// mapping_start + mapping_len]`.
#[derive(Clone, Copy)]
pub struct IdnaRow {
    /// The first code point of the row.
    pub first: u32,
    /// The last code point of the row.
    pub last: u32,
    /// The Status.
    pub status: Status,
    /// Where the mapping starts in `IDNA_MAPPING_DATA`.
    pub mapping_start: u32,
    /// The mapping's length.
    pub mapping_len: u32,
}

/// A code point's full canonical decomposition, `DECOMPOSITION_DATA[start
/// .. start + len]`.
#[derive(Clone, Copy)]
pub struct DecompositionRow {
    /// The code point.
    pub code_point: u32,
    /// Where its decomposition starts in `DECOMPOSITION_DATA`.
    pub start: u32,
    /// The decomposition's length.
    pub len: u32,
}

/// A primary composite `composite`, canonically equivalent to `<first,
/// second>`.
#[derive(Clone, Copy)]
pub struct CompositionRow {
    /// L.
    pub first: u32,
    /// C.
    pub second: u32,
    /// P.
    pub composite: u32,
}

/// Code points `first..=last` with Canonical_Combining_Class `class`.
#[derive(Clone, Copy)]
pub struct ClassRow {
    /// The first code point of the range.
    pub first: u32,
    /// The last code point of the range.
    pub last: u32,
    /// The Canonical_Combining_Class.
    pub class: u8,
}

/// Code points `first..=last`.
#[derive(Clone, Copy)]
pub struct RangeRow {
    /// The first code point of the range.
    pub first: u32,
    /// The last code point of the range.
    pub last: u32,
}

/// The Bidi_Class values (UAX #44 long names; the short ones RFC 5893
/// uses are in each doc comment).
#[derive(Clone, Copy)]
pub enum BidiClass {
    /// L
    LeftToRight,
    /// R
    RightToLeft,
    /// AL
    ArabicLetter,
    /// EN
    EuropeanNumber,
    /// ES
    EuropeanSeparator,
    /// ET
    EuropeanTerminator,
    /// AN
    ArabicNumber,
    /// CS
    CommonSeparator,
    /// NSM
    NonspacingMark,
    /// BN
    BoundaryNeutral,
    /// B
    ParagraphSeparator,
    /// S
    SegmentSeparator,
    /// WS
    WhiteSpace,
    /// ON
    OtherNeutral,
    /// LRE
    LeftToRightEmbedding,
    /// LRO
    LeftToRightOverride,
    /// RLE
    RightToLeftEmbedding,
    /// RLO
    RightToLeftOverride,
    /// PDF
    PopDirectionalFormat,
    /// LRI
    LeftToRightIsolate,
    /// RLI
    RightToLeftIsolate,
    /// FSI
    FirstStrongIsolate,
    /// PDI
    PopDirectionalIsolate,
}

/// Code points `first..=last` with Bidi_Class `class`.
#[derive(Clone, Copy)]
pub struct BidiRow {
    /// The first code point of the range.
    pub first: u32,
    /// The last code point of the range.
    pub last: u32,
    /// The Bidi_Class.
    pub class: BidiClass,
}

/// The Joining_Type values other than U (Non_Joining).
#[derive(Clone, Copy)]
pub enum JoiningType {
    /// C
    JoinCausing,
    /// D
    DualJoining,
    /// L
    LeftJoining,
    /// R
    RightJoining,
    /// T
    Transparent,
}

/// Code points `first..=last` with Joining_Type `joining_type`.
#[derive(Clone, Copy)]
pub struct JoiningRow {
    /// The first code point of the range.
    pub first: u32,
    /// The last code point of the range.
    pub last: u32,
    /// The Joining_Type.
    pub joining_type: JoiningType,
}

} // verus!
